#requires -Version 7.4
param([string]$Root,[ValidateSet('Plan','Apply')][string]$Action='Plan',[string]$ExpectedDigest,[string]$Reason)
. "$PSScriptRoot/agent-core.ps1"
if(-not $Root){$Root=Get-AgentRoot};$Root=[IO.Path]::GetFullPath($Root)
$dirs=@('ledger/runs','ledger/artifacts','ledger/events','ledger/writes','ledger/deployments','state/tasks','state/hooks')
$files=[Collections.Generic.List[string]]::new();foreach($dir in $dirs){$full=Resolve-SafePath $Root ".agents/runtime/$dir";if(Test-Path $full){foreach($file in Get-ChildItem -LiteralPath $full -File -Filter '*.json'){$files.Add([IO.Path]::GetRelativePath($Root,$file.FullName).Replace('\','/'))}}};foreach($run in Get-ChildItem -LiteralPath (Resolve-SafePath $Root '.agents/runtime/runs') -Directory -Filter 'run-*' -ErrorAction SilentlyContinue){$task=Join-Path $run.FullName 'task';if(Test-Path $task){foreach($file in Get-ChildItem -LiteralPath $task -File -Filter '*.json'){$files.Add([IO.Path]::GetRelativePath($Root,$file.FullName).Replace('\','/'))}}}
$index=Resolve-SafePath $Root '.agents/runtime/state/memory-index.json';if(Test-Path $index){$files.Add('.agents/runtime/state/memory-index.json')}
$map=[ordered]@{'agents-project/v4'='agents-project/v5';'agents-knowledge/v4'='agents-knowledge/v5';'agents-task/v4'='agents-task/v5';'agents-task-pointer/v4'='agents-task-pointer/v5';'agents-validation/v4'='agents-validation/v5';'agents-artifact/v4'='agents-artifact/v5';'agents-runtime-policy/v4'='agents-runtime-policy/v5';'agents-runtime-event/v4'='agents-runtime-event/v5';'agents-run/v4'='agents-run/v5';'agents-cleanup-plan/v4'='agents-cleanup-plan/v5';'agents-write/v4'='agents-write/v5';'agents-hook-state/v4'='agents-hook-state/v5';'agents-memory-index/v4'='agents-memory-index/v5'}
$changes=@();foreach($relative in $files){$full=Resolve-SafePath $Root $relative;$text=[IO.File]::ReadAllText($full);$updated=$text;foreach($key in $map.Keys){$updated=$updated.Replace($key,$map[$key])};if($updated -cne $text){$changes+=@(@{path=$relative;before=(Get-TextHash $text);after=(Get-TextHash $updated)})}}
$plan=[ordered]@{schema_version='agents-runtime-migration-plan/v5';root=$Root;from_version='v4';to_version='v5';files=$changes;protections=@('Only registered ledger/state JSON paths are scanned.','Payload directories and links are never recursively traversed.','Apply requires an exact digest and reviewed reason.')};$plan.digest=Get-TextHash (ConvertTo-AgentCanonicalJson $plan)
if($Action -eq 'Plan'){$plan|ConvertTo-Json -Depth 30 -Compress;exit 0}
if(-not $ExpectedDigest -or $ExpectedDigest -ne $plan.digest){throw 'Apply requires the exact reviewed runtime migration plan digest.'};if([string]::IsNullOrWhiteSpace($Reason)){throw 'Apply requires a reviewed reason.'}
foreach($change in $changes){$full=Resolve-SafePath $Root $change.path;$text=[IO.File]::ReadAllText($full);foreach($key in $map.Keys){$text=$text.Replace($key,$map[$key])};if((Get-TextHash $text) -ne $change.after){throw "Runtime metadata changed: $($change.path)"};[IO.File]::WriteAllText($full,$text,[Text.UTF8Encoding]::new($false))}
foreach($pointerFile in Get-ChildItem -LiteralPath (Resolve-SafePath $Root '.agents/runtime/state/tasks') -File -Filter '*.json' -ErrorAction SilentlyContinue){$pointer=Read-AgentJson $pointerFile.FullName;$revision=Resolve-SafePath $Root $pointer.path;if(Test-Path $revision){$pointer.sha256=Get-AgentHash $revision;Write-AgentJson $pointerFile.FullName $pointer -Root $Root;if($pointer.artifact_id){$recordPath=Get-RuntimePath $Root "ledger/artifacts/$($pointer.artifact_id).json";if(Test-Path $recordPath){$record=Read-AgentJson $recordPath;$base=Get-RuntimeFootprint $Root $pointer.base_path;$record.sha256=$base.digest;$record.items=$base.items;Write-AgentJson $recordPath $record -Root $Root}}}}
@{status='migrated';plan_digest=$plan.digest;files=$changes.Count;reason=$Reason}|ConvertTo-Json -Compress
